const D = { density:.55, scale:1, hue:200, energy:.6, speed:1, x:.5, y:.8, sway:.6, spread:.85, style:'matte', act:'drift', seed:0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const clp=(v,a,b)=>Math.max(a,Math.min(b,v));
const frc=v=>v-Math.floor(v);
const md=(a,n)=>((a%n)+n)%n;
const lrp=(a,b,t)=>a+(b-a)*t;
const fr=i=>{const s=Math.sin(i*127.1+P.seed*311.7)*43758.5453;return s-Math.floor(s);};

const W=width,Hh=height,u=Math.min(W,Hh);
const H=md(P.hue,360);
const st=P.style;
const matte=st==='matte',riso=st==='riso',foil=st==='foil',wire=st==='wire',ink=st==='ink';
const en=P.energy*(0.55+0.6*K.intensity);
const spanY=Hh*1.35;

if(S.lastBeat==null||K.beat<S.lastBeat)S.lastBeat=K.beat;
S.lastBeat=K.beat;

// ---- build unit balloon sprite (once per size-bucket + style + seed) ----
const bucket=Math.round(u*0.16);
const key=bucket+'|'+st;
if((matte||foil||riso)&&(S.sprKey!==key)){
  S.sprKey=key;
  const sg=Math.max(24,bucket);
  const g=createGraphics(sg,sg*1.28);
  g.colorMode(HSB,360,100,100,100);
  g.clear();
  const cxs=sg*0.5, cys=sg*0.5, r=sg*0.46;
  const ctx=g.drawingContext;
  const grd=ctx.createRadialGradient(cxs-r*0.32,cys-r*0.42,r*0.08, cxs,cys+r*0.05,r*1.05);
  if(foil){ grd.addColorStop(0,'#ffffff'); grd.addColorStop(0.28,'#f2f2f2'); grd.addColorStop(0.55,'#8a8a8a'); grd.addColorStop(0.8,'#e8e8e8'); grd.addColorStop(1,'#4a4a4a'); }
  else if(riso){ grd.addColorStop(0,'#ffffff'); grd.addColorStop(1,'#ffffff'); }
  else { grd.addColorStop(0,'#ffffff'); grd.addColorStop(0.55,'#cfcfcf'); grd.addColorStop(1,'#6f6f6f'); }
  ctx.fillStyle=grd;
  g.push(); g.translate(cxs,cys); g.beginShape();
  for(let a=0;a<=32;a++){ const th=a/32*Math.PI*2; const rr=r*(1+0.07*Math.cos(th*1)-0.04); const px=Math.cos(th-Math.PI/2)*rr*1.0; const py=Math.sin(th-Math.PI/2)*rr*1.16; g.vertex(px,py); }
  g.endShape(CLOSE); g.pop();
  // knot
  g.noStroke(); g.fill(0,0,60,100); g.triangle(cxs-sg*0.03,cys+r*1.06,cxs+sg*0.03,cys+r*1.06,cxs,cys+r*1.16);
  if(riso){
    // halftone dot texture baked (2-ink misregistration look): dark dots on lower-right
    g.noStroke();
    for(let yy=0;yy<sg*1.28;yy+=Math.max(3,sg*0.09)){
      for(let xx=0;xx<sg;xx+=Math.max(3,sg*0.09)){
        const dx=(xx-cxs), dy=(yy-cys*1.02); const dd=Math.sqrt(dx*dx+dy*dy)/(r*1.2);
        if(dd<1){ const shade=clp((dd-0.15)*1.3,0,1); const rad=(sg*0.045)*shade; if(rad>0.4){ g.fill(0,0,20,60); g.ellipse(xx+sg*0.02,yy+sg*0.02,rad,rad); } }
      }
    }
  } else {
    // specular highlight
    g.noStroke(); g.fill(0,0,100,foil?90:70); g.ellipse(cxs-r*0.34,cys-r*0.4,r*0.34,r*0.5);
    if(foil){ g.fill(0,0,100,80); g.push(); g.translate(cxs+r*0.12,cys-r*0.1); g.rotate(-0.5); g.rect(-r*0.04,-r*0.55,r*0.08,r*1.0,r*0.04); g.pop(); }
  }
  S.spr=g;
}

// ---- balloon field (rebuild on seed) ----
if(S.seedUsed!==P.seed){ S.seedUsed=P.seed; S.bl=[]; for(let i=0;i<48;i++){ S.bl.push({bx:fr(i*3+1),ho:(fr(i*3+2)-0.5)*70,ph:fr(i*3+3),sp:0.5+fr(i*3+4)*0.9,sw:0.4+fr(i*3+5),sz:0.6+fr(i*3+6)*0.7,tw:fr(i*3+7)*6.28}); } }

const nB=Math.round(lrp(6,34,clp(P.density,0,1)));
const swAmp=W*0.06*P.sway*(0.6+en);
const buoy=1+K.pulse*0.18*en+A.bass*0.5;                 // beat lift + bass
const actUpdraft=P.act==='updraft', actBob=P.act==='bob';
const riseRate=0.055*P.speed*(actUpdraft?(0.7+K.intensity*0.9+A.bass*0.6):1);

push();
if(foil||riso) blendMode(BLEND);
for(let i=0;i<nB;i++){
  const b=S.bl[i];
  const life=frc(b.ph + K.t*riseRate*b.sp);
  const bx=(lrp(0.5-0.5*P.spread,0.5+0.5*P.spread,b.bx))*W + b.ho*(u/900) + Math.sin(K.t*b.sw*(actBob?1.7:1)*P.speed + b.tw)*swAmp;
  const by=Hh*1.18 - life*spanY*buoy;
  const bs=u*0.13*P.scale*b.sz*(0.9+0.1*Math.sin(K.t*3+b.tw));
  const fade=clp(life*6,0,1)*clp((1-life)*5,0,1);
  const hh=md(H + b.ho*0.6, 360);
  if(fade<=0.02) continue;
  // string
  const sx2=bx+Math.sin(K.t*1.2+b.tw)*bs*0.25;
  stroke(hh, ink?12:35, ink?30:80, 22*fade); strokeWeight(Math.max(1,u*0.0015)); noFill();
  line(bx, by+bs*0.62, sx2, by+bs*1.5);
  if(wire){
    // abstract latitude/longitude wireframe globe — non-representational
    noFill(); push(); translate(bx,by);
    const sat=lrp(60,95,fade);
    for(let m=0;m<5;m++){ const rr=bs*0.5*(1-Math.abs(m-2)/2.6); const yo=(m-2)/2.4*bs*0.5; stroke(hh,sat,95,60*fade); strokeWeight(Math.max(0.8,u*0.0012)); ellipse(0,yo,rr*2,rr*0.5); }
    for(let m=0;m<6;m++){ const a=m/6*Math.PI; stroke(md(hh+20,360),sat,90,50*fade); ellipse(0,0,bs*Math.abs(Math.cos(a))*1.0+2,bs*1.16); }
    stroke(hh,40,100,90*fade); point(-bs*0.18,-bs*0.2);
    pop();
    noStroke(); fill(hh,60,80,15*fade); ellipse(bx,by,bs*0.9,bs*1.05);
  } else if(ink){
    // sumi wash — soft tonal blob with bleed, no hard outline
    noStroke(); const ic=lrp(18,42,1-fade);
    for(let r=3;r>0;r--){ const t=r/3; fill(hh,10,ic,(r===3?10:22)*fade); ellipse(bx+Math.sin(b.tw+r)*bs*0.05, by, bs*0.92*(1+ (3-r)*0.06)*t*3/3*1, bs*1.14*(1+(3-r)*0.05)); }
    fill(hh,6,clp(ic+18,0,80),30*fade); ellipse(bx-bs*0.15,by-bs*0.18,bs*0.28,bs*0.36);
    fill(0,0,18,40*fade); triangle(bx-bs*0.05,by+bs*0.55,bx+bs*0.05,by+bs*0.55,bx,by+bs*0.66);
  } else if(S.spr){
    // matte / foil / riso sprite with hue tint
    const sat=riso?78:foil?42:70, br=foil?100:90;
    push(); translate(bx,by);
    tint(hh,sat,br,clp(fade,0,1)*100);
    imageMode(CENTER);
    image(S.spr, 0, bs*0.08, bs, bs*1.28);
    if(riso){ // misregistration ghost (2nd ink offset)
      tint(md(hh+150,360),70,95,clp(fade,0,1)*38);
      image(S.spr, u*0.006, bs*0.08+u*0.004, bs, bs*1.28);
    }
    noTint(); pop();
  }
}
pop();
blendMode(BLEND);
noTint();
